/* cppi::f466d92d609610b4ccc5d9845d27cfd6db67f3be918647f0c088ee5a428b5eed */
SELECT * FROM ci_etl_db_dev.ci_capital_pipeline_consolidated
                WHERE CAST(extract_timestamp AS TIMESTAMP) = TIMESTAMP '2025-06-18 23:19:05'

/* cppi::0703e8434d42ff28d9317a5f60423704a8fb6585db6d3bec144c7c84f916348e */
-- Athena JDBC driver connection test
SELECT 1

/* cppi::f2da25e990838955f7f23f7a10767a778f7c3d852d9297676a126249ad23325c */
select id_isin as identifier, cppib_sec_id as ID_CPPIBSEC, ticker_exch_cd as ticker from asset.qsrp_security_equity_latest
     where id_isin is not null and cppib_sec_id is not null

/* cppi::4fe4cea2574536bc97746224b1d72e437fcc8e8e8e9c54ad597311678e339876 */
SELECT cppib_sec_id, rating_value FROM performance.cppib_security_rating
                WHERE business_date = '2025-05-28' AND rating_agency = 'CPPIB'

/* cppi::06c211665d2eeebaf8f4c73860c3c15efadaeb90ca74f57bd3d5bfa2d525c543 */
select cppib_sec_id , bloomberg_unique_id , cusip, sedol, isin, ticker from asset.asset_security_identifiers asi where business_date = date '2025-06-18' and cppib_sec_id = 29240659

LIMIT 200

/* cppi::7a0684a3de549b3aef0fbfaea899933d901a8b1094608396cbd347e7f41a8853 */
WITH unified_assets AS (SELECT cppib_sec_id AS ID_CPPIBSEC, business_date AS BUSINESS_DT, cppib_party_id AS ID_CPPIBPRTY, country_code AS CNTRY, NULL AS DOMICILE_CNTRY, NULL AS INCORP_CNTRY, currency_code AS CRNCY, market_sector_description AS MARKET_SECTOR_DESC, source_security_type AS SRC_SEC_TYP, source_security_type_2 AS SRC_SEC_TYP2, instrument_description AS SEC_DESC, instrument_name AS SEC_NM, NULL AS ID_BB_SECURITY, bloomberg_unique_id AS ID_BB_UNIQUE, NULL AS ID_CUSIP, NULL AS ID_SEDOL, NULL AS ID_ISIN, NULL AS ID_TICKER, 0 AS FREE_FLOAT_PCT, 0 AS SHR_OUT, 0 AS SHR_OUT_REAL, NULL AS PRTY_NM, NULL AS GICS_SECTOR_CD, NULL AS GICS_SECTOR_NM, NULL AS GICS_INDUSGRP_CD, NULL AS GICS_INDUSGRP_NM, NULL AS GICS_INDUSTRY_CD, NULL AS GICS_INDUSTRY_NM, NULL AS GICS_SUBINDUS_CD, NULL AS GICS_SUBINDUS_NM, bloomberg_ticker_and_exchange AS TICKER_EXCH_CD, market_status_code AS MARKET_STATUS, bloomberg_primary_listing_exchange_flag AS PRIMARY_FLG, NULL AS ID_BB_COMPANY, NULL AS ID_BB_PARENT_CO, listing_country_code AS COUNTRY_TRADE, 0 AS ROUND_LOT_SIZE, 0 AS QUOTE_LOT_SIZE, underlying_instrument_cppib_sec_id AS UNDL_ID_CPPIBSEC, NULL AS UNDL_SEDOL, NULL AS CNTRY_NM, issue_country_iso AS ISSUE_CNTRY, 0 AS SHR_TOT_OUT, 0 AS SHR_OUT_TOT_MULT_SH FROM asset.asset_warrants_universe WHERE source_security_type_2 = 'Right' AND delete_date IS NULL UNION ALL SELECT cppib_sec_id AS ID_CPPIBSEC, business_date AS BUSINESS_DT, cppib_party_id AS ID_CPPIBPRTY, country_code AS CNTRY, NULL AS DOMICILE_CNTRY, NULL AS INCORP_CNTRY, currency_code AS CRNCY, market_sector_description AS MARKET_SECTOR_DESC, source_security_type AS SRC_SEC_TYP, source_security_type_2 AS SRC_SEC_TYP2, instrument_description AS SEC_DESC, instrument_name AS SEC_NM, NULL AS ID_BB_SECURITY, bloomberg_unique_id AS ID_BB_UNIQUE, NULL AS ID_CUSIP, NULL AS ID_SEDOL, NULL AS ID_ISIN, NULL AS ID_TICKER, 0 AS FREE_FLOAT_PCT, 0 AS SHR_OUT, 0 AS SHR_OUT_REAL, NULL AS PRTY_NM, NULL AS GICS_SECTOR_CD, NULL AS GICS_SECTOR_NM, NULL A