ence_exchange_codes_map recm ON recm.exchange_code = s.bloomberg_exchange AND recm.product_code = 'Equity' AND recm.composite_name <> '' WHERE s.source_security_type_2 IN ('Common Stock', 'Depositary Receipt', 'Unit', 'Mutual Fund', 'REIT', 'Preference', 'Partnership Shares') AND s.delete_date IS NULL AND s.bloomberg_ticker_and_exchange IS NOT NULL), ranked_data AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY ID_CPPIBSEC, ID_CUSIP, ID_SEDOL, ID_ISIN, ID_TICKER ORDER BY BUSINESS_DT DESC) AS rn FROM unified_assets) SELECT * FROM ranked_data WHERE rn = 1 ORDER BY "ID_BB_PARENT_CO" DESC
