/* cppi::93f86f814b4bc6eb4f4d14a682f5b3d02e05659aab5d222d4852f4aeeaace12f */
/* QuickSight 964bf937-b4e0-4541-876a-66af8637a24d */
SELECT "billing_period", "usage_date", "payer_account_id", "linked_account_id", "account_name", "region_code", "rds_type", "deployment_option", "original_deployment_option", "original_usage_type", "engine", "engineversion", "instance_type_family", "instance_type", "item_description", "dbinstanceidentifier", "resource_id", "vcpus", "usage_unit", "usage_amount", "vcpu_acu_hours", "year_1_start", "is_year_1_2", "year_3_start", "is_year_3", "end_of_extended_support", "is_unsupported", "year_1_2_pricing", "year_1_2_cost", "year_3_pricing", "year_3_cost"
FROM "AwsDataCatalog"."cid_cur"."rds_extended_support_view"

/* cppi::2f18d1680b1279075b4fc134d687327d09ee5f9a25f00255d5006a1c97f210d5 */
select business_date as date_, security_id, 'SP500_25' as strategy_id, weight_ndo as weight
